// Reference airports drawn on the scope, and the coastline polygons
// (generated by tools/gen_coastline.py into coastline_data.cpp).
#pragma once

#include <cstddef>

#include "geo.h"

namespace radar {

// One runway with its two landing thresholds.
struct Runway {
  const char* ident[2];  // e.g. {"17", "35"}
  LatLon threshold[2];   // threshold of ident[0], threshold of ident[1]
};

struct Place {
  const char* code;
  const char* name;
  LatLon pos;
  const Runway* runways = nullptr;
  size_t runwayCount = 0;
};

extern const Place kAirports[];
extern const size_t kAirportCount;

// The airport within 3 NM of `pos`, or nullptr.
const Place* airportNear(const LatLon& pos);

struct CoastPolygon {
  const char* name;
  const float* latlon;  // interleaved lat, lon pairs; closed ring
  size_t count;         // number of points
};

extern const CoastPolygon kCoastline[];
extern const size_t kCoastlineCount;

}  // namespace radar
